export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // oldest -> newest
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined

      const now = clock()
      if (now > entry.expiresAt) {
        entries.delete(key)
        return undefined
      }

      entry.lastUsed = now
      entries.delete(key)
      entries.set(key, entry)
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.has(key)) {
        entries.delete(key)
      } else if (entries.size >= capacity) {
        // Map iteration order tracks recency, so the first key is the LRU entry.
        entries.delete(entries.keys().next().value)
      }
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
    },

